def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda v: sum(row.count(v) for row in grid))
    colors = {grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != bg}
    # Extend each diagonal run of at least two matching cells outwards from both ends.
    for color in colors:
        pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == color}
        for dc in (-1, 1):
            for r, c in pts:
                if (r + 1, c + dc) not in pts:
                    continue
                if (r - 1, c - dc) in pts:
                    continue
                endr, endc = r + 1, c + dc
                while (endr + 1, endc + dc) in pts:
